    '}',
    '.komvox-chat-typing-dot:nth-child(2) { animation-delay: 0.2s; }',
    '.komvox-chat-typing-dot:nth-child(3) { animation-delay: 0.4s; }',
    '.komvox-chat-input-area {',
    '  border-top: 1px solid #EFEFEF;',
