    '  align-items: center;',
    '  justify-content: center;',
    '  transition: transform 0.15s, opacity 0.15s;',
    '  margin-bottom: 1px;',
    '}',
    '.komvox-chat-send-btn:hover:not(:disabled) { transform: scale(1.08); }',
    '.komvox-chat-send-btn:focus { outline: none; box-shadow: 0 0 0 3px rgba(0,217,255,0.3); }',
    '.komvox-chat-send-btn:disabled { opacity: 0.45; cursor: not-allowed; }',
    '.komvox-chat-footer {',
    '  text-align: center;',
    '  font-size: 11px;',
    '  color: #999999;',
