    '  from { opacity: 0; transform: translateY(8px); }',
    '  to   { opacity: 1; transform: translateY(0); }',
    '}',
    '@keyframes komvox-pulse {',
    '  0%, 60%, 100% { transform: scale(1);   opacity: 0.5; }',
    '  30%            { transform: scale(1.4); opacity: 1;   }',
    '}',
